function ib($sv,$en){ return ' <button type="button" class="ib" data-i="'.h(t($sv,$en)).'" aria-label="info">i</button>'; }
function f($label,$name,$def,$type='text',$extra='',$inf=''){ return '<label class="f"><span>'.$label.$inf.'</span><input name="'.$name.'" type="'.$type.'" value="'.h(setting($name,$def)).'" '.$extra.'></label>'; }
function sf($label,$name,$extra=''){ return '<label class="f">'.$label.'<input name="'.$name.'" type="password" value="'.(setting($name,'')!==''?'********':'').'" autocomplete="new-password" onfocus="this.select()" '.$extra.'></label>'; }
function opts($name,$list,$cur){ $o='<select name="'.$name.'">'; foreach($list as $k=>$n) $o.='<option value="'.h(is_int($k)?$n:$k).'"'.((is_int($k)?$n:$k)===$cur?' selected':'').'>'.h($n).'</option>'; return $o.'</select>'; }
ob_start(function($b){ $f=function($h){ return preg_replace_callback('/<input\b([^>]*)>/i',function($m){ $a=$m[1]; if(preg_match('/type=["\'](hidden|checkbox|radio|submit)["\']/i',$a)) return $m[0]; $x=''; foreach(['data-bwignore="true"','data-1p-ignore','data-lpignore="true"','data-form-type="other"'] as $at){ if(stripos($a,strtok($at,'='))===false) $x.=' '.$at; } if(stripos($a,'autocomplete=')===false) $x.=' autocomplete="off"'; return '<input'.$a.$x.'>'; },$h); }; $p=preg_split('/(<script\b.*?<\/script>)/is',$b,-1,PREG_SPLIT_DELIM_CAPTURE); foreach($p as $i=>$x) if($i%2===0) $p[$i]=$f($x); return implode('',$p); });
