<script>(function(){var L=LANG==='en'?['Normal','Warning','Critical']:['Normal','Varning','Kritisk'];document.querySelectorAll('.thr:not(.cert)').forEach(function(b){var n=b.querySelector('[name$=_n]'),w=b.querySelector('[name$=_w]'),bar=b.querySelectorAll('.thr-bar i'),tx=b.querySelector('.thr-t');
var M=+b.getAttribute('data-max'),U=b.getAttribute('data-u');
function draw(){var a=+n.value,c=+w.value;bar[0].style.width=(a/M*100)+'%';bar[1].style.width=((c-a)/M*100)+'%';bar[2].style.width=((M-c)/M*100)+'%';tx.textContent=L[0]+' 0–'+a+U+'  ·  '+L[1]+' '+(a+1)+'–'+c+U+'  ·  '+L[2]+' >'+c+U}
n.oninput=function(){if(+w.value<=+n.value)w.value=Math.min(M-1,+n.value+1);if(+n.value>=+w.value)n.value=+w.value-1;draw()};
w.oninput=function(){if(+n.value>=+w.value)n.value=+w.value-1;draw()};draw()})})();</script>
<script>(function(){var b=document.querySelector('.thr.cert');if(!b)return;var c=b.querySelector('[name=thr_cert_c]'),w=b.querySelector('[name=thr_cert_w]'),bar=b.querySelectorAll('.thr-bar i'),tx=b.querySelector('.thr-t'),M=365,en=LANG==='en',d=en?' d':' d';
function draw(){var x=+c.value,y=+w.value;bar[0].style.width=(x/M*100)+'%';bar[1].style.width=((y-x)/M*100)+'%';bar[2].style.width=((M-y)/M*100)+'%';tx.textContent=(en?'Critical <':'Kritisk <')+x+d+'  ·  '+(en?'Warning ':'Varning ')+x+'–'+(y-1)+d+'  ·  '+(en?'Normal ≥':'Normal ≥')+y+d}
c.oninput=function(){if(+w.value<=+c.value)w.value=Math.min(364,+c.value+1);if(+c.value>=+w.value)c.value=+w.value-1;draw()};w.oninput=function(){if(+c.value>=+w.value)c.value=+w.value-1;draw()};draw()})();</script>
</div>
