<script>(function(){var sec=document.getElementById('oidsec'),box=document.getElementById('oids'),en=LANG==='en',nx=box.children.length+100,TPL=<?= json_encode(oid_sel('__I__',[],$SRVL)) ?>,T=document.querySelector('input[name=t]').value,st=sec.querySelector('.ast'),tm=null,busy=false,again=false;
function lab(d){var n=d.querySelectorAll('input[type=checkbox]:checked').length;d.querySelector('.mst').textContent=(en?'Choose device(s)':'Välj enhet(er)')+(n?' ('+n+')':'')}
function save(){if(busy){again=true;return}busy=true;var b=new URLSearchParams();b.set('t',T);b.set('a','save_oids');b.set('ajax','1');[].forEach.call(box.querySelectorAll('input'),function(i){if(i.name&&(i.type!=='checkbox'||i.checked))b.append(i.name,i.value)});st.textContent=en?'Saving…':'Sparar…';
 return fetch('settings.php',{method:'POST',credentials:'same-origin',headers:{'Content-Type':'application/x-www-form-urlencoded'},body:b.toString()}).then(function(r){return r.json()}).then(function(d){st.textContent=d.ok?(en?'Saved ✓':'Sparat ✓'):(en?'Not saved':'Inte sparat')}).catch(function(){st.textContent=en?'Not saved':'Inte sparat'}).then(function(){busy=false;if(again){again=false;save()}})}
function later(){clearTimeout(tm);tm=setTimeout(save,350)}
function row(nm,ov,ids){var i=nx++,d=document.createElement('div');d.className='orow';d.innerHTML='<input name="oid_name['+i+']" data-bwignore="true" autocomplete="off"><input name="oid_val['+i+']" size="42" data-bwignore="true" autocomplete="off">'+TPL.split('__I__').join(i)+'<button type="button" class="btn sm danger rm">✕</button>';d.querySelector('[name^=oid_name]').value=nm;d.querySelector('[name^=oid_val]').value=ov;[].forEach.call(d.querySelectorAll('input[type=checkbox]'),function(c){c.checked=ids.indexOf(c.value)>=0});box.appendChild(d);lab(d.querySelector('.msel'))}
var ent=document.getElementById('oent');box.addEventListener('change',function(e){var m=e.target.closest('.msel');if(m)lab(m);later()});ent.addEventListener('change',function(e){var m=e.target.closest('.msel');if(m)lab(m)});[].forEach.call(sec.querySelectorAll('.msel'),lab);document.addEventListener('click',function(e){[].forEach.call(sec.querySelectorAll('.msel[open]'),function(m){if(!m.contains(e.target))m.removeAttribute('open')})});
document.getElementById('oadd').onclick=function(){var o=ent.querySelector('.eo'),n=ent.querySelector('.en');if(!o.value.trim()){o.focus();return}var ids=[].map.call(ent.querySelectorAll('input[type=checkbox]:checked'),function(c){return c.value});row(n.value,o.value.trim(),ids);n.value='';o.value='';[].forEach.call(ent.querySelectorAll('input[type=checkbox]'),function(c){c.checked=false});lab(ent.querySelector('.msel'));clearTimeout(tm);save()};
