<script>(function(){var sec=document.getElementById('discsec'),st=sec.querySelector('.ast'),tm=null,busy2=false,cancel=false,again=false,box=document.getElementById('drows'),res=document.getElementById('dres'),en=LANG==='en',T=document.querySelector('input[name=t]').value,nx=box.children.length+100,KINDS=<?= json_encode(disc_kinds(),JSON_UNESCAPED_UNICODE) ?>,busy=false;
function esc(s){return String(s).replace(/[&<>"]/g,function(c){return{'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[c]})}
function post(o){var b=new URLSearchParams();for(var k in o){if(Array.isArray(o[k]))o[k].forEach(function(v){b.append(k+'[]',v)});else b.set(k,o[k])}b.set('t',T);return fetch('api/discover.php',{method:'POST',credentials:'same-origin',headers:{'Content-Type':'application/x-www-form-urlencoded'},body:b.toString()}).then(function(r){return r.json()})}
function rowHtml(i){return '<input type="hidden" name="disc_id['+i+']" value=""><input name="disc_net['+i+']" placeholder="10.10.10.0/24" size="20"><input name="disc_comm['+i+']" type="password" size="20" autocomplete="new-password" placeholder="'+(en?'Community (default)':'Community (standard)')+'"><button type="button" class="btn sm dscan">'+(en?'Scan':'Skanna')+'</button><button type="button" class="btn sm danger drm">✕</button>'}
function dsave(){if(busy2){again=true;return}busy2=true;var b=new URLSearchParams();b.set('t',T);b.set('a','save_disc');b.set('ajax','1');[].forEach.call(box.querySelectorAll('input'),function(i){if(i.name)b.append(i.name,i.value)});st.textContent=en?'Saving…':'Sparar…';
 return fetch('settings.php',{method:'POST',credentials:'same-origin',headers:{'Content-Type':'application/x-www-form-urlencoded'},body:b.toString()}).then(function(r){return r.json()}).then(function(d){if(d.ok){st.textContent=d.bad?(en?'Saved – a network has an invalid format':'Sparat – ett nät har fel format'):(en?'Saved ✓':'Sparat ✓');var m=d.map||{};[].forEach.call(box.querySelectorAll('.drow'),function(r){var n=r.querySelector('[name^=disc_net]'),ix=n.name.replace(/\D/g,''),id=m[ix];if(id){r.querySelector('[name^=disc_id]').value=id;var c=r.querySelector('[name^=disc_comm]');if(c.value&&c.value!=='********')c.value='********'}})}else st.textContent=en?'Not saved':'Inte sparat'}).catch(function(){st.textContent=en?'Not saved':'Inte sparat'}).then(function(){busy2=false;if(again){again=false;dsave()}})}
box.addEventListener('change',function(){clearTimeout(tm);tm=setTimeout(dsave,350)});
document.getElementById('dadd').onclick=function(){var e=document.getElementById('dent'),n=e.querySelector('.en'),c=e.querySelector('.ec');if(!n.value.trim()){n.focus();return}var d=document.createElement('div');d.className='orow drow';d.innerHTML=rowHtml(nx++);d.querySelector('[name^=disc_net]').value=n.value.trim();d.querySelector('[name^=disc_comm]').value=c.value;box.appendChild(d);n.value='';c.value='';clearTimeout(tm);dsave()};
box.addEventListener('click',function(e){var r=e.target.closest('.drow');if(!r)return;if(e.target.classList.contains('drm')){r.remove();clearTimeout(tm);dsave()}if(e.target.classList.contains('dscan'))scan(r)});
function scan(r){if(busy)return;var net=r.querySelector('[name^=disc_net]').value.trim(),comm=r.querySelector('[name^=disc_comm]').value,id=r.querySelector('[name^=disc_id]').value;if(!net){res.innerHTML='<p class="mut">'+(en?'Enter a network first, for example 10.10.10.0/24.':'Ange ett nät först, till exempel 10.10.10.0/24.')+'</p>';return}
 busy=true;cancel=false;res.innerHTML='<p class="mut"><span id="dprog">'+(en?'Preparing…':'Förbereder…')+'</span> <button type="button" class="btn sm" id="dcancel">'+(en?'Cancel':'Avbryt')+'</button></p>';document.getElementById('dcancel').onclick=function(){cancel=true;this.disabled=true};post({a:'expand',net:net}).then(function(d){if(cancel){busy=false;res.innerHTML='';return}if(!d.ok){res.innerHTML='<p class="badt">'+esc(d.error)+'</p>';busy=false;return}
  var ips=d.ips,chunks=[],found=[],done=0,fail=null,alive=0,pg=document.getElementById('dping').checked?1:0;for(var i=0;i<ips.length;i+=16)chunks.push(ips.slice(i,i+16));var q=chunks.slice(),pr=document.getElementById('dprog');
  function upd(){pr.textContent=(en?'Scanning ':'Skannar ')+d.net+' … '+Math.min(done,ips.length)+'/'+ips.length+(pg?' ('+alive+(en?' replied to ping, ':' svarade på ping, ')+found.length+(en?' answered SNMP)':' svarade på SNMP)'):' ('+found.length+(en?' found)':' hittade)'))}upd();
  function worker(){var c=q.shift();if(!c||fail||cancel)return Promise.resolve();return post({a:'scan',ips:c,comm:comm,id:id,ping:pg}).then(function(x){if(!x.ok)fail=x.error;else{found=found.concat(x.found);alive+=x.alive}done+=c.length;upd();return worker()}).catch(function(){fail=en?'Request failed':'Anropet misslyckades'})}
  Promise.all([worker(),worker()]).then(function(){busy=false;if(cancel){res.innerHTML='<p class="mut">'+(en?'Scan cancelled.':'Skanningen avbröts.')+'</p>';return}if(fail){res.innerHTML='<p class="badt">'+esc(fail)+'</p>';return}show(found,d.net,comm,id)})})}
function show(f,net,comm,id){f.sort(function(a,b){return a.ip.split('.').reduce(function(s,x){return s*256+ +x},0)-b.ip.split('.').reduce(function(s,x){return s*256+ +x},0)});
 if(!f.length){res.innerHTML='<p class="mut">'+(en?'No devices answered SNMP in ':'Inga enheter svarade på SNMP i ')+esc(net)+'.</p>';return}
 var h='<p><b>'+f.length+'</b> '+(en?'devices answered in ':'enheter svarade i ')+esc(net)+'.</p><table class="card"><tr><th></th><th>IP</th><th>'+(en?'Name':'Namn')+'</th><th>'+(en?'Description':'Beskrivning')+'</th><th>'+(en?'Add as':'Lägg till som')+'</th></tr>';
 f.forEach(function(x,i){var o='';for(var k in KINDS)o+='<option value="'+k+'"'+(k===x.guess.kind?' selected':'')+'>'+esc(KINDS[k])+'</option>';h+='<tr data-i="'+i+'"'+(x.exists?' class="dim"':'')+'><td><input type="checkbox" class="dsel"'+(x.exists?' disabled':' checked')+'></td><td>'+esc(x.ip)+'</td><td><input class="dnm" value="'+esc(x.name||x.ip)+'" size="22"'+(x.exists?' disabled':'')+'></td><td class="det" title="'+esc(x.descr)+'">'+esc(x.descr.slice(0,70))+'</td><td>'+(x.exists?'<small>'+(en?'already added':'redan tillagd')+'</small>':'<select class="dkind">'+o+'</select>')+'</td></tr>'});
 h+='</table><button type="button" class="btn" id="dgo">'+(en?'Add selected':'Lägg till valda')+'</button> <button type="button" class="btn" id="dclose">'+(en?'Cancel':'Avbryt')+'</button> <span id="dmsg" class="mut"></span>';res.innerHTML=h;document.getElementById('dclose').onclick=function(){res.innerHTML=''};
 document.getElementById('dgo').onclick=function(){var items=[];res.querySelectorAll('tr[data-i]').forEach(function(tr){var c=tr.querySelector('.dsel');if(!c||c.disabled||!c.checked)return;var x=f[+tr.getAttribute('data-i')];items.push({ip:x.ip,name:tr.querySelector('.dnm').value,kind:tr.querySelector('.dkind').value,descr:x.descr,oid:x.oid})});
  if(!items.length)return;this.disabled=true;post({a:'add',items:JSON.stringify(items),comm:comm,id:id}).then(function(r){document.getElementById('dgo').disabled=false;var m=document.getElementById('dmsg');if(!r.ok){m.textContent=r.error;return}m.className=r.errors.length?'badt':'okt';m.textContent=r.added+(en?' device(s) added. ':' enhet(er) tillagda. ')+r.errors.join('; ');items.forEach(function(it){res.querySelectorAll('tr[data-i]').forEach(function(tr){if(f[+tr.getAttribute('data-i')].ip===it.ip){tr.classList.add('dim');tr.querySelectorAll('input,select').forEach(function(i){i.disabled=true})}})})})}}
})();</script>
