<h3><?= t('Lagring','Storage') ?></h3>
<?php $lst=null; try{ $pi=log_part_info(); $ti=db()->query("SELECT TABLE_ROWS r,DATA_LENGTH d,INDEX_LENGTH i FROM information_schema.TABLES WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME='log_events'")->fetch(); $old=db()->query('SELECT ts FROM log_events ORDER BY id LIMIT 1')->fetchColumn(); $d1=(int)db()->query('SELECT COUNT(*) FROM log_events WHERE ts>=NOW()-INTERVAL 1 DAY')->fetchColumn(); $lst=['pi'=>$pi,'ti'=>$ti,'old'=>$old,'d1'=>$d1]; }catch(Throwable $e){ $lst=null; } ?>
<?php if(!$lst||!$lst['ti']): ?><p class="mut"><?= t('Ingen lagringsstatistik ännu (tabellen log_events saknas eller är tom).','No storage statistics yet (the log_events table is missing or empty).') ?></p><?php else: $mb=($lst['ti']['d']+$lst['ti']['i'])/1048576; $days=$lst['old']?max(1,(time()-strtotime($lst['old']))/86400):1; $kp=(int)setting('log_keep',30); $perday=$mb/$days; ?>
<table class="card" style="max-width:640px"><tr><td><?= t('Antal händelser (ungefär)','Events (approx.)') ?></td><td><?= number_format((int)$lst['ti']['r'],0,',',' ') ?></td></tr>
<tr><td><?= t('Storlek (data + index)','Size (data + index)') ?></td><td><?= $mb>=1024?round($mb/1024,2).' GB':round($mb).' MB' ?></td></tr>
